import{RULES}from'./config.js';
import{median}from'./stats.js';
const aliases={promotion_started_days_before:'days_promoted_before',instagram_reach_before_meeting:'reach',meeting_type:'type',meeting_time:'time',promotion_channels:'promotion',instagram_reach:'reach',social_reach:'reach',member_ids:'members',meeting_name:'name',signups_before_meeting:'signups'};
export const OPTIONAL=['type','time','promotion','reach','signups','members'];
export const canonicalHeader=x=>{const k=String(x).replace(/^\uFEFF/,'').trim().toLowerCase().replace(/[ -]+/g,'_');return aliases[k]??k};
const text=x=>x==null?'':String(x).trim();
const known={workshop:'Workshop',discussion:'Discussion',presentation:'Presentation',social:'Social',activity:'Activity',competition:'Competition','guest speaker':'Guest speaker',lunch:'Lunch','after school':'After school',evening:'Evening',instagram:'Instagram',posters:'Posters',discord:'Discord',remind:'Remind','word of mouth':'Word of mouth','classroom announcement':'Announcements','classroom announcements':'Announcements','interactive activity':'Interactive Activity','before school':'Before School',announcements:'Announcements','club rush':'Club Rush','no promotion':'No promotion'};
function category(v,key){const s=text(v).replace(/\s+/g,' ');if(!s||s==='Unknown')return null;if(s.length>150)throw Error(`${key} must be at most 150 characters.`);if(key==='promotion')return [...new Set(s.split(/\s*(?:\+|;|\||,)\s*/).filter(Boolean).map(x=>known[x.toLowerCase()]??x))].sort().join(' + ');return known[s.toLowerCase()]??s}
function numeric(v,key,required=false){if(v==null||text(v)===''){if(required)throw Error(`${key} is required.`);return null}const n=Number(v);if(!Number.isInteger(n)||n<0||n>(key==='reach'?10000000:100000))throw Error(`${key} must be a nonnegative whole number within the supported limit.`);return n}
function normalize(raw,index){const r={};for(const[k,v]of Object.entries(raw)){const key=canonicalHeader(k);if(key in r)throw Error(`Both ${key} and an alias were provided.`);r[key]=v}
let date=text(r.date);const usDate=date.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(usDate)date=`${usDate[3]}-${usDate[1].padStart(2,'0')}-${usDate[2].padStart(2,'0')}`;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date))||new Date(date).toISOString().slice(0,10)!==date)throw Error('Use a real date in YYYY-MM-DD or M/D/YYYY (month/day/year) format.');
const attendance=numeric(r.attendance,'attendance',true),name=text(r.name)||text(r.topic)||`Meeting ${index}`;if(name.length>150)throw Error('name must be at most 150 characters.');
const row={id:text(r.id)||`row-${index}`,name,date,attendance,type:null,time:null,promotion:null,reach:null,signups:null,members:null,new_members:null,returning_members:null,topic:null,days_promoted_before:null,special_event:null,notes:null};const issues=[];
for(const key of ['type','time','promotion']){try{row[key]=category(r[key],key)}catch(e){issues.push({field:key,reason:e.message})}}
for(const key of ['reach','signups','new_members','returning_members','days_promoted_before']){try{row[key]=numeric(r[key],key)}catch(e){issues.push({field:key,reason:e.message})}}
const recordWarnings=[];if(row.new_members!=null&&row.returning_members!=null&&row.new_members+row.returning_members!==attendance)recordWarnings.push('New + returning members does not equal attendance. Counts are preserved; inconsistent counts are excluded from member analysis.');
for(const key of ['new_members','returning_members'])if(row[key]>attendance)recordWarnings.push(key+' exceeds attendance. Value is preserved for correction.');
for(const key of ['topic','notes']){if(text(r[key]).length>(key==='notes'?1000:150))issues.push({field:key,reason:key+' is too long.'});else row[key]=text(r[key])||null}
const special=text(r.special_event).toLowerCase();if(special){if(['yes','true','1','no','false','0'].includes(special))row.special_event=['yes','true','1'].includes(special);else issues.push({field:'special_event',reason:'Use Yes or No for special_event.'})}
const ids=Array.isArray(r.members)?r.members.map(text):text(r.members)?text(r.members).split(';').map(text).filter(Boolean):null;
if(ids){if(new Set(ids).size!==ids.length||ids.length!==attendance||ids.some(x=>!x||x.length>80))issues.push({field:'members',reason:'Member IDs must be unique, at most 80 characters, and match attendance.'});else row.members=ids}else if(attendance===0)row.members=[];
row.channels=row.promotion?row.promotion.split(' + '):[];return{row,issues,recordWarnings,normalizations:['type','time','promotion'].filter(k=>text(r[k])&&row[k]!==text(r[k])).map(field=>({field,from:text(r[field]),to:row[field]}))}}
export function validateRow(raw,index=1){const {row,issues}=normalize(raw,index);if(issues.length)throw Error(`Row ${index}: ${issues.map(i=>i.reason).join(' ')}`);return row}
export function assessDataset(rawRows){if(!Array.isArray(rawRows)||rawRows.length>RULES.maxRows)throw Error(`Use an array with at most ${RULES.maxRows} meetings.`);const rows=[],excludedRows=[],fieldIssues=[],normalizations=[],duplicates=[],recordWarnings=[],seen=new Map(),usedIds=new Set();
rawRows.forEach((raw,i)=>{const sourceRow=raw?.sourceRow??i+1;try{if(!raw||typeof raw!=='object')throw Error('Expected a meeting record.');const n=normalize(raw,sourceRow);const r=n.row;const fingerprint=JSON.stringify([String(raw.name??raw.meeting_name??'').trim().toLowerCase(),r.date,r.attendance,r.type,r.time,r.promotion,r.reach,r.signups,r.members?[...r.members].sort():null,r.new_members,r.returning_members,r.topic,r.days_promoted_before,r.special_event,r.notes]);if(seen.has(fingerprint)){const duplicateOf=seen.get(fingerprint);duplicates.push({row:sourceRow,duplicateOf});excludedRows.push({row:sourceRow,reason:`Exact duplicate of row ${duplicateOf}.`});return}seen.set(fingerprint,sourceRow);if(usedIds.has(r.id))r.id=`${r.id}-${i+1}`;usedIds.add(r.id);rows.push(r);recordWarnings.push(...n.recordWarnings.map(reason=>({row:sourceRow,reason})));fieldIssues.push(...n.issues.map(x=>({row:sourceRow,...x})));normalizations.push(...n.normalizations.map(x=>({row:sourceRow,...x})))}catch(e){excludedRows.push({row:sourceRow,reason:e.message})}});
const missingFields=Object.fromEntries(OPTIONAL.map(k=>[k,rows.filter(r=>r[k]==null).length]));const baseline=median(rows.map(r=>r.attendance));const suspicious=rows.filter(r=>r.attendance>1000||(baseline>0&&r.attendance>baseline*5)).map(r=>({id:r.id,reason:'Unusually large attendance; retained for your review.'}));const groups=Object.fromEntries(['type','time','promotion'].map(k=>[k,new Set(rows.map(r=>r[k]).filter(Boolean)).size]));
const readiness={descriptive:rows.length>0,comparisons:rows.length>=RULES.comparisons,correlation:rows.filter(r=>r.reach!=null).length>=RULES.correlation,forecasting:rows.length>=RULES.forecast&&rows.filter(r=>rows.filter(p=>p.date<r.date).length>=RULES.training).length>=RULES.testCases,retention:rows.length>0&&missingFields.members===0};
const warnings=recordWarnings.map(x=>`Row ${x.row}: ${x.reason}`);const dates=new Map();for(const r of rows)dates.set(r.date,(dates.get(r.date)??0)+1);for(const [date,n]of dates)if(n>1)warnings.push(`${n} meetings share ${date}; retained because their records differ.`);if(rows.some(r=>r.notes?.includes('Example row - delete before using')))warnings.push('Template example rows are still present. Replace or remove them before analyzing your club.');if(excludedRows.length)warnings.push(`${excludedRows.length} rows excluded; inspect the reasons below.`);if(fieldIssues.length)warnings.push(`${fieldIssues.length} invalid optional values are excluded only from the affected analyses.`);if(suspicious.length)warnings.push(`${suspicious.length} attendance values need review; no outliers were removed.`);for(const k of OPTIONAL)if(missingFields[k])warnings.push(`${missingFields[k]} meetings have no usable ${k}.`);if(rows.length<RULES.forecast)warnings.push(`At least ${RULES.forecast} meetings on different dates are needed for forecasting.`);if(Object.values(groups).some(n=>n>RULES.maxCategories))warnings.push('High-cardinality categories use the rolling-average forecast instead of regression.');
return{rows,quality:{totalRows:rawRows.length,usableRows:rows.length,duplicateRows:duplicates.length,duplicates,missingFields,warnings,excludedRows,fieldIssues,normalizations,recordWarnings,suspicious,analysisReadiness:readiness,categoryCounts:groups}}}
export function parseCSVRecords(textValue){if(typeof textValue!=='string'||new TextEncoder().encode(textValue).length>RULES.maxBytes)throw Error('Choose a CSV smaller than 3 MB.');let row=[],cell='',quoted=false,closed=false;const matrix=[];for(let i=0;i<textValue.length;i++){const c=textValue[i];if(quoted){if(c==='"'){if(textValue[i+1]==='"'){cell+='"';i++}else{quoted=false;closed=true}}else cell+=c;continue}if(c==='"'){if(cell||closed)throw Error('Unexpected quote in CSV.');quoted=true}else if(c===','){row.push(cell);cell='';closed=false}else if(c==='\r'||c==='\n'){if(c==='\r'&&textValue[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))matrix.push(row);row=[];cell='';closed=false}else if(closed&&!/\s/.test(c))throw Error('Unexpected text after a quoted CSV field.');else if(!closed)cell+=c}if(quoted)throw Error('The CSV has an unclosed quoted field.');row.push(cell);if(row.some(x=>x.trim()))matrix.push(row);if(matrix.length<2)throw Error('Add a header row and at least one meeting.');const headers=matrix.shift().map(x=>{return canonicalHeader(x)});if(headers.some(k=>!k)||new Set(headers).size!==headers.length)throw Error('CSV column names and aliases must be unique and nonempty.');const missing=['date','attendance'].filter(k=>!headers.includes(k));if(missing.length)throw Error('Missing columns: '+missing.join(', '));if(matrix.length>RULES.maxRows)throw Error(`Import up to ${RULES.maxRows} meetings.`);const allowed=new Set(['name','date','attendance',...OPTIONAL,'new_members','returning_members','topic','days_promoted_before','special_event','notes']);return{records:matrix.map((values,i)=>{if(values.length!==headers.length)throw Error(`Row ${i+2}: column count does not match the header.`);return{...Object.fromEntries(headers.filter(h=>allowed.has(h)).map(h=>[h,values[headers.indexOf(h)].trim()])),sourceRow:i+2}}),ignoredColumns:headers.filter(h=>!allowed.has(h))}}
export function importCSV(text){const parsed=parseCSVRecords(text),result=assessDataset(parsed.records);result.quality.ignoredColumns=parsed.ignoredColumns;if(parsed.ignoredColumns.length)result.quality.warnings.push(`Unused columns ignored: ${parsed.ignoredColumns.join(', ')}.`);return result}
export function parseCSV(text){return importCSV(text).rows}
